    console.log("Skipping follow-up test: token is missing");
    done();
    return;
  }

  pm.sendRequest({
    url: `${baseUrl}/rentals`,
    method: "GET",
    header: {
      "Authorization": `Bearer ${token}`
    }
  }, function (err, res) {
    pm.expect(err, "Request failed").to.be.null;
    pm.expect(res.code, "Status code is not 200").to.equal(200);
    pm.expect(res.responseTime, "Response time is too high").to.be.below(1000);

    const data = res.json();
    // Ensure we handle the response correctly regardless of structure
    const list = Array.isArray(data) ? data : (data.rentals || []);
    pm.expect(list, "Response data is not an array").to.be.an("array");
    done();
  });
});

