pm.test("POST /rentals passing case creates Reserved rental with C5 math", function () {
    pm.expect(pm.response.code).to.be.oneOf([200, 201]);
    pm.expect(pm.response.responseTime).to.be.below(1000);

    const data = pm.response.json();
    const rental = data.rental || data;

    pm.expect(rental).to.include.all.keys(
        "id",
        "customerId",
        "itemId",
        "status",
        "startDate",
        "days",
        "rentalTotal",
        "deposit"
    );

    // Save ID before price assertions so follow-up GET targets the newly created rental
    pm.environment.set("createdRentalId", rental.id);

    pm.expect(rental.status).to.equal("Reserved");
    pm.expect(Number(rental.days)).to.equal(3);

    // Rule C5: I-2 = 85.00/day * 3 days = 255.00 gross; 10% discount -> 229.50; 20% deposit -> 45.90
    pm.expect(Number(rental.rentalTotal)).to.equal(229.5);
    pm.expect(Number(rental.deposit)).to.equal(45.9);
});

